L21_1 = "\227\130\183\227\130\176\227\131\158\227\128\129\231\167\129\227\129\159\227\129\161\227\129\175\228\186\186\233\150\147\227\129\168\227\129\175\233\129\149\227\129\134\227\129\174\227\128\130\227\129\157\227\129\151\227\129\166\228\186\186\233\150\147\229\144\140\229\163\171\227\129\167\227\130\130\233\129\149\227\129\134\227\128\130"
