L20_1.m_Talk_VTN = L21_1
L21_1 = "\232\165\191\230\160\188\231\142\155\239\188\140\230\136\145\228\187\172\232\183\159\228\186\186\231\177\187\228\184\141\228\184\128\230\160\183\227\128\130\232\128\140\228\184\148\239\188\140\228\186\186\231\177\187\232\183\159\228\186\186\231\177\187\228\185\159\228\184\141\228\184\128\230\160\183\227\128\130"
