L22_1 = "\227\129\130\227\129\170\227\129\159\227\129\168\231\167\129\227\129\175\227\129\168\227\129\166\227\130\130\230\129\181\227\129\190\227\130\140\227\129\166\227\130\139\227\130\147\227\129\160\227\130\136\227\128\130\227\129\157\227\130\140\227\129\140\228\189\149\227\129\139\227\130\143\227\129\139\227\130\139\239\188\159"
